#[value(tag="mutation",rename_all="camelCase")]
enum Operation{InsertAnnualScheduleRule(crate::InsertAnnualScheduleRule),RemoveAnnualScheduleRule(crate::RemoveAnnualScheduleRule),ReorderAnnualScheduleRules(crate::ReorderAnnualScheduleRules),AddAnnualScheduleHoliday(crate::AddAnnualScheduleHoliday),RemoveAnnualScheduleHoliday(crate::RemoveAnnualScheduleHoliday),ChangeWeeklyScheduleDay(crate::ChangeWeeklyScheduleDay)}
macro_rules! from{($($name:ident),*)=>{$(impl From<crate::$name> for Operation{fn from(v:crate::$name)->Self{Self::$name(v)}})*}}
from!(InsertAnnualScheduleRule,RemoveAnnualScheduleRule,ReorderAnnualScheduleRules,AddAnnualScheduleHoliday,RemoveAnnualScheduleHoliday,ChangeWeeklyScheduleDay);
impl protocol::Mutation<EnergyModelSnapshot> for Operation{type Diff=EnergyModelDiff;const DESCRIPTORS:&'static[protocol::MutationLeafDescriptor]=&[];fn descriptor(&self)->&'static protocol::MutationLeafDescriptor{panic!("actual schedule laws invoke the installed authored leaf directly")}}
fn run<L>(case:&serde_json::Value,law:&serde_json::Value)where L:RetainedMutationLeaf<EnergyModelSnapshot,Operation>+NativeReceive<DslValue>+RetireOwned+Sync{
 let body=law["bodyBytes"].as_u64().unwrap()as usize;let mut doc:serde_json::Value=serde_json::from_str(include_str!("../../../../📸️snapshot/🧬️original/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut doc=doc["document"].take();doc["model"]=helpers::corpus()["model"].clone();doc["model"]["schedules"]["daily"]=serde_json::json!([{"id":1,"hourly_values":vec![1.0;24],"interpolation":"Discrete","limits":null},{"id":2,"hourly_values":vec![0.5;24],"interpolation":"Discrete","limits":null},{"id":3,"hourly_values":vec![0.0;24],"interpolation":"Discrete","limits":null}]);let annual=serde_json::json!({"id":10,"rules":law["rules"],"default_daily_schedule_id":1,"holiday_daily_schedule_id":null,"holiday_dates":law["holidays"]});let weekly=serde_json::json!({"id":20,"daily_schedule_ids":law["days"]});doc["model"]["schedules"]["annual"]=serde_json::json!([annual]);doc["model"]["schedules"]["weekly"]=serde_json::json!([weekly]);let week=case["action"]=="change-day";let collection=if week{"weekly"}else{"annual"};doc["model"]["schedules"][collection][0][case["field"].as_str().unwrap()]=case["before"].clone();let original=source(if case.get("retainedSource").and_then(serde_json::Value::as_bool)==Some(true){helpers::receive_retained::<EnergyModelSnapshot>(&doc)}else{receive::<EnergyModelSnapshot>(&doc)});let input=source(receive::<L>(&case["payload"]));
 let factory=semio_framework_value::factory::OwnedValueRetirementFactory::<Operation>::default();let context=RetainedMutationCloseContext{mutations:&factory};
 for cut in std::iter::once(None).chain(law["cancelAt"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){let mut owner=L::Preparation::new();let mut ready=false;for turn in 0..cut.unwrap_or(100000){let d=owner.decision_demand(input.borrow(),original.borrow(),body).unwrap();assert!(d.capacity_bytes<=16<<20);let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.decide(input.borrow(),original.borrow(),body,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.decision_demand(input.borrow(),original.borrow(),body).unwrap(),d);}let(s,h)=observe(||owner.decide(input.borrow(),original.borrow(),body,g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));assert!(s.progress().fits(g));if matches!(s,RetainedMutationAdvance::Ready(_)){ready=true;break}assert!(turn<99999,"{} actual schedule leaf did not finish",case["id"]);}
 let mut diff=None;let mut inverse=None;if cut.is_none(){assert!(ready);match owner.take_decision(){RetainedMutationDecision::Refused(messages)=>{assert!(!matches!(case["outcome"].as_str(),Some("changed"|"no-op")),"{} refused",case["id"]);assert_eq!(messages.len(),1);assert_eq!(messages[0].code.0.as_str(),if case["outcome"]=="invalid"{"mutation.invariant"}else{"mutation.target-missing"});let target=if case["outcome"]=="invalid-reference"{case["payload"].get("dailyScheduleId").unwrap_or(&case["payload"]["newDailyScheduleId"])}else{&case["payload"]["id"]};assert_eq!(messages[0].target,[target.as_u64().unwrap().to_string()]);drain(messages)},RetainedMutationDecision::Admitted(value,messages)=>{assert!(matches!(case["outcome"].as_str(),Some("changed"|"no-op")),"{} admitted",case["id"]);if case["outcome"]=="no-op"{assert_eq!(messages.len(),1);assert_eq!(messages[0].code.0.as_str(),"mutation.no-op");}else{assert!(messages.is_empty())}drain(messages);let value=source(value);for turn in 0..100000{let d=owner.inverse_demand(input.borrow(),original.borrow(),value.borrow(),body).unwrap();assert!(d.capacity_bytes<=16<<20);let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.inverse(input.borrow(),original.borrow(),value.borrow(),body,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));}let(s,h)=observe(||owner.inverse(input.borrow(),original.borrow(),value.borrow(),body,g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if matches!(s,RetainedMutationAdvance::Ready(_)){break}assert!(turn<99999)}let operations=owner.take_inverse();if case["outcome"]=="changed"{assert_eq!(operations.len(),1);assert_portable_value(operations[0].to_value(),&case["inverse"]);let mut post=project_record(original.borrow());assert!(central_fragment(&value,original.borrow(),&mut post));let schedules=post.model.outputs.get().schedules.get();let actual=if week{schedules.weekly.get(0).unwrap().daily_schedule_ids.get().to_value()}else{let row=schedules.annual.get(0).unwrap();if case["field"]=="rules"{row.rules.get().to_value()}else{row.holiday_dates.get().to_value()}};assert_portable_value(actual,&case["after"]);macro_rules! unchanged{($($branch:ident),*)=>{$(assert_eq!(post.model.$branch.identity(),original.borrow().get().model.$branch.identity());)*};}unchanged!(identity,geometry,materials,loads,controls,systems,generation);drain(post);}else{assert!(operations.is_empty())}inverse=Some(operations);diff=Some(value);}}}
 owner.begin_close();for turn in 0..100000{if owner.terminal_is_empty(){break}let d=owner.close_demand(context,body).unwrap();assert!(d.capacity_bytes<=16<<20);let g=grant(d);for denied in denied_axes(g,d){let(s,h)=observe(||owner.close_step(context,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.close_demand(context,body).unwrap(),d);}let(s,h)=observe(||owner.close_step(context,g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));assert!(turn<99999,"{} actual schedule closure did not finish",case["id"]);}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));if let Some(v)=inverse{drain(v)}if let Some(v)=diff{drain(v)}
 }drain(input);drain(original);
}
#[test]fn six_original_schedule_intents_keep_exact_rank_day_inverse_and_physical_custody(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for case in law["cases"].as_array().unwrap(){match case["action"].as_str().unwrap(){"insert-rule"=>run::<crate::InsertAnnualScheduleRule>(case,&law),"remove-rule"=>run::<crate::RemoveAnnualScheduleRule>(case,&law),"reorder-rules"=>run::<crate::ReorderAnnualScheduleRules>(case,&law),"add-holiday"=>run::<crate::AddAnnualScheduleHoliday>(case,&law),"remove-holiday"=>run::<crate::RemoveAnnualScheduleHoliday>(case,&law),"change-day"=>run::<crate::ChangeWeeklyScheduleDay>(case,&law),_=>unreachable!()}}}

#[test]fn wide_original_schedule_rules_move_one_admitted_item_at_a_time_and_keep_exact_inverse(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();assert_eq!(law["wideSourceAdmission"],"original-retained-turns");let count=law["wideRuleCount"].as_u64().unwrap()as usize;let mut case=law["cases"].as_array().unwrap().iter().find(|case|case["action"]=="reorder-rules"&&case["outcome"]=="changed").unwrap().clone();case["retainedSource"]=serde_json::json!(true);let before=(0..count).map(|rank|law["rules"][rank%3].clone()).collect::<Vec<_>>();let mut after=before.clone();after.rotate_left(1);case["before"]=serde_json::json!(before);case["after"]=serde_json::json!(after);case["payload"]=serde_json::json!({"id":10,"from":0,"to":count-1});case["inverse"]=serde_json::json!({"mutation":"reorderAnnualScheduleRules","id":10,"from":count-1,"to":0});run::<crate::ReorderAnnualScheduleRules>(&case,&law);}

